import {cards,stages,finalQuiz,glossary} from './content.js?v=tiangong-2';
import {STORAGE_KEY,fresh,restore,mastered,certificateReady,esc} from './state.js?v=tiangong-2';
import {scene} from './visuals.js';
import {mountRateLab,mountEquilibriumLab} from './labs.js';
import {mountActivity} from './activities.js?v=tiangong-2';
let state=fresh(),canStore=true,current=1;try{state=restore(JSON.parse(localStorage.getItem(STORAGE_KEY)||'null'));}catch{canStore=false;}
const $=id=>document.getElementById(id),controllers=new Map();
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));canStore=true;}catch{canStore=false;}route();document.dispatchEvent(new Event('ch4-records'));updateCertificate();}
function route(){const n=cards.filter(c=>mastered(c,state)).length;$('mastery-label').textContent=$('top-progress').textContent=`${n} / 10`;$('mastery-progress').value=n;$('storage-note').textContent=canStore?'觀察與作答進度會自動保存。':'瀏覽器目前無法保存。請用手札匯出紀錄。';for(const a of $('route').querySelectorAll('a')){const id=Number(a.dataset.id),done=mastered(cards[id-1],state);a.classList.toggle('mastered',done);a.querySelector('i').textContent=done?'✓':'○';a.querySelector('i').setAttribute('aria-label',done?'已掌握':'待探索');if(id===current)a.setAttribute('aria-current','step');else a.removeAttribute('aria-current');}}
$('route').innerHTML=cards.map(c=>`<a href="#card-${c.id}" data-id="${c.id}"><span>${String(c.id).padStart(2,'0')}</span><span>${c.title}</span><i>○</i></a>`).join('');
function quizMarkup(q){return `<div class="quiz-item" data-quiz="${q.id}"><h3>${q.question}</h3><div class="quiz-options">${q.options.map((t,i)=>`<button class="quiz-option" data-answer="${i}" aria-pressed="false"><span>${String.fromCharCode(65+i)}</span>${esc(t)}</button>`).join('')}</div><p class="feedback" role="status"></p><button class="text-button quiz-retry" hidden>重新作答</button></div>`;}
function bindQuiz(host,q,get,set){const sync=()=>{const ans=get();host.querySelectorAll('[data-answer]').forEach(b=>{const selected=ans===Number(b.dataset.answer);b.classList.toggle('right',selected&&ans===q.answer);b.classList.toggle('wrong',selected&&ans!==q.answer);b.setAttribute('aria-pressed',String(selected));});const fb=host.querySelector('.feedback');fb.className='feedback '+(ans===null||ans===undefined?'':ans===q.answer?'correct':'retry');fb.textContent=ans===null||ans===undefined?'':`${ans===q.answer?'✓ 答對了。':'再想一想。'}${q.explanations[ans]}${ans===q.answer?'':` 提示：${q.hint} 正確答案是 ${String.fromCharCode(65+q.answer)}：${q.options[q.answer]}。`}`;host.querySelector('.quiz-retry').hidden=ans===null||ans===undefined;};host.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{set(Number(b.dataset.answer));sync();save();}));host.querySelector('.quiz-retry').addEventListener('click',()=>{set(null);sync();save();host.querySelector('[data-answer]').focus();});sync();return sync;}
function assessmentMarkup(id,title,questions){return `<section class="assessment" id="${id}" aria-labelledby="${id}-title"><div class="assessment-head"><div><span class="step-label">把證據變成自己的理解</span><h2 id="${id}-title">${title}</h2></div><span data-score>0 / ${questions.length}</span></div><p>每題都有解析，可以重新作答。全部答對後，這一階段就完成了。</p>${questions.map(quizMarkup).join('')}</section>`;}
function mountAssessment(host,id,qs){state.assessments[id]||={};const tally=()=>{const n=qs.filter(q=>state.assessments[id][q.id]===q.answer).length;host.querySelector('[data-score]').textContent=n+' / '+qs.length;host.classList.toggle('all-correct',n===qs.length);};qs.forEach(q=>bindQuiz(host.querySelector(`[data-quiz="${q.id}"]`),q,()=>state.assessments[id][q.id]??null,v=>{state.assessments[id][q.id]=v;tally();}));tally();}
function mountCard(c){const article=document.createElement('article');article.id='card-'+c.id;article.dataset.card=c.id;article.className='exploration-card';article.tabIndex=-1;article.setAttribute('aria-labelledby',`card-${c.id}-title`);$('lesson').append(article);let s=state.cards[c.id],cleanup=()=>{};const find=sel=>article.querySelector(sel);const ready=()=>c.required.every(k=>s.evidence.includes(k));
 function record(key){if(s.prediction===null||!c.required.includes(key)||s.evidence.includes(key))return;s.evidence.push(key);sync();save();}
 function sync(){find('[data-activity]').inert=s.prediction===null;find('.prediction-preview-note').hidden=s.prediction!==null;find('.discovery').hidden=!ready();find('.practice').hidden=!(ready()&&s.quizOpen);find('[data-understood]').hidden=s.quizOpen;find('[data-review]').hidden=!(s.prediction!==null&&s.evidence.length);find('[data-review]').textContent=s.prediction!==null?'我原先猜：'+c.choices[s.prediction]+'　現在，試著用觀察證據修正或支持它。':'';find('.evidence-list').innerHTML=c.required.map((k,i)=>`<li class="${s.evidence.includes(k)?'done':''}"><span>${s.evidence.includes(k)?'✓':'○'}</span>${c.labels[i]}</li>`).join('');find('[data-locked-explanation]').hidden=ready();}
 function prediction(){const host=find('.prediction-block');host.innerHTML=s.prediction!==null?`<div class="prediction-saved"><span class="prediction-icon">✓</span><div><small>操作前的猜想 · 已留下</small><h4>${c.prediction}</h4><p>${c.choices[s.prediction]}</p><span class="prediction-note">帶著這個想法操作，看看證據會怎麼回答。</span></div></div>`:`<div class="prediction-heading"><span class="prediction-icon">?</span><div><small>先猜一猜 · 操作前</small><h4>${c.prediction}</h4><p>選一個現在的想法；還不確定也可以。</p></div></div><form class="prediction-form"><fieldset><legend class="prediction-legend">我目前的猜想</legend>${c.choices.map((t,i)=>`<label class="prediction-choice"><input type="radio" name="prediction-${c.id}" value="${i}"><span>${t}</span></label>`).join('')}</fieldset><div class="prediction-submit-row"><button class="primary" type="submit" disabled>留下猜想，開始探索 →</button></div></form>`;const form=host.querySelector('form');if(form){form.addEventListener('change',()=>form.querySelector('button').disabled=false);form.addEventListener('submit',e=>{e.preventDefault();const value=form.querySelector('input:checked');if(!value)return;s.prediction=Number(value.value);prediction();sync();save();find('[data-activity]').scrollIntoView({block:'start',behavior:'smooth'});});}}
 function render(){cleanup();article.innerHTML=`<header class="chapter-header"><div class="chapter-kicker"><span>${c.act}</span><div>${c.type} · ${String(c.id).padStart(2,'0')} / 10 <button class="card-reset" data-reset aria-label="重設第 ${c.id} 卡">↺</button></div></div><h2 id="card-${c.id}-title">${c.title}</h2><p class="core-question">${c.question}</p></header><div class="chapter-body">${c.scene!==undefined?scene(c.scene,['','','小葵與阿公比較反應速度。','一小匙黑色粉末，帶來新的疑問。','同一只密閉瓶，藏著雙向的變化。','答案，就寫在兩人共同的科學手札裡。'][c.scene]||'木匣裡的沙漏與紙條，帶來三道時間謎題。','card-scene'):''}<p class="opening">${c.opening}</p><div class="story-dialogue" aria-label="小葵與阿公的對話">${['kui','grandpa'].map((who,i)=>`<div class="story-speech story-speech--${who}"><span class="story-portrait story-portrait--${who}" data-expression="${c.expressions[i]}" aria-hidden="true"></span><p><b>${i?'阿公':'小葵'}</b>${c.dialogue[i]}</p></div>`).join('')}</div><div class="learning-goal"><b>這次的任務</b><span>${c.goal}</span></div><section class="prediction-block" aria-label="第 ${c.id} 卡預測"></section><p class="prediction-preview-note">① 在上方選一個猜想並保存，② 再依下方任務操作。</p><section class="chapter-activity" data-activity aria-label="第 ${c.id} 卡探索活動"></section><div class="prediction-review" data-review hidden></div><div class="evidence-panel"><span class="step-label">已留下的線索</span><ul class="evidence-list"></ul></div><p class="locked-explanation" data-locked-explanation>完成上方列出的觀察，就能把線索連成完整解釋。</p><section class="discovery" hidden><span class="step-label">把觀察連成解釋</span><h3>${c.conceptTitle}</h3><ul class="concept-points">${c.points.map(p=>`<li>${p}</li>`).join('')}</ul><div class="reaction-equation">${c.equation}</div><button class="primary" data-understood>我理解了，試一題 <span>→</span></button></section><section class="practice" hidden><span class="step-label">小試身手</span>${quizMarkup(c.quiz)}</section><div class="chapter-bridge"><span class="step-label">${c.id===10?'寫進手札的最後一頁':'接著探索 '+String(c.id+1).padStart(2,'0')}</span><p>${c.bridge}</p></div></div><footer class="chapter-footer">${c.id>1?`<a href="#card-${c.id-1}" class="previous">← 上一張</a>`:''}<button class="text-button" data-reset>重設本卡</button><a class="next" href="${stages[c.id]?'#stage-'+c.id:c.id===10?'#certificate':'#card-'+(c.id+1)}">${stages[c.id]?'進入階段測驗':c.id===10?'查看學習成果':'帶著線索往下走'} <b>→</b></a></footer>`;
 prediction();const ctx={record,save,allState:state,isUnlocked:()=>s.prediction!==null};cleanup=[2,4,5].includes(c.id)?mountRateLab(find('[data-activity]'),c.id,s,ctx):[8,9].includes(c.id)?mountEquilibriumLab(find('[data-activity]'),c.id,s,ctx):mountActivity(find('[data-activity]'),c.id,s,ctx);
 bindQuiz(find('.quiz-item'),c.quiz,()=>s.answer,v=>{s.answer=v;sync();});find('[data-understood]').addEventListener('click',()=>{s.quizOpen=true;sync();save();find('.practice').scrollIntoView({block:'center',behavior:'smooth'});});article.querySelectorAll('.chapter-header [data-reset], .chapter-footer [data-reset]').forEach(b=>b.addEventListener('click',()=>{s=state.cards[c.id]=fresh().cards[c.id];render();save();article.focus({preventScroll:true});}));sync();}
 render();controllers.set(c.id,{sync,cleanup:()=>cleanup()});if(stages[c.id]){const wrap=document.createElement('div');wrap.innerHTML=assessmentMarkup('stage-'+c.id,stages[c.id].title,stages[c.id].questions);const assessment=wrap.firstElementChild;$('lesson').append(assessment);mountAssessment(assessment,'stage-'+c.id,stages[c.id].questions);}}
cards.forEach(mountCard);
const cert=document.createElement('section');cert.id='certificate';cert.className='certificate';cert.innerHTML=`<span class="certificate-seal">⌛</span><p class="eyebrow">SCIENCE LAB · CHAPTER 04</p><h2>時間煉金術研究員證書</h2><p data-certificate-status></p><div data-certificate-unlocked hidden><p>你用觀察、實驗與證據，解開了皇帝的三道時間謎題。</p><label>研究員姓名 <input id="researcher-name" placeholder="寫下你的名字" maxlength="30"></label><p class="certificate-motto">看見變化的速度，也理解不變中的流動。</p><button class="primary" id="print-certificate">列印／另存證書 PDF</button></div>`;$('lesson').append(cert);
function updateCertificate(){if(!$('certificate'))return;const ready=certificateReady(state);cert.querySelector('[data-certificate-unlocked]').hidden=!ready;cert.querySelector('[data-certificate-status]').textContent=ready?'✓ 10 張探索卡、3 階段測驗，全部完成。':`完成 10 張卡片並答對所有階段測驗，即可解鎖。目前卡片：${cards.filter(c=>mastered(c,state)).length} / 10。`;cert.classList.toggle('unlocked',ready);}
$('print-certificate').addEventListener('click',()=>{if(certificateReady(state))window.print();});
function activate(){let active=1;for(const c of cards)if($('card-'+c.id).getBoundingClientRect().top<innerHeight*.35)active=c.id;if(active!==current){current=active;route();}}
let ticking=false;addEventListener('scroll',()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{activate();ticking=false;});},{passive:true});addEventListener('hashchange',()=>{const m=location.hash.match(/^#card-(\d+)$/);if(m&&cards[Number(m[1])-1]){current=Number(m[1]);route();$('card-'+current).focus({preventScroll:true});}});
function showGlossary(){const term=$('glossary-search').value.trim();const list=glossary.filter(([k,v])=>(k+v).includes(term));$('glossary-list').innerHTML=list.length?list.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join(''):'<p>沒有找到這個詞，試試「速率」或「平衡」。</p>';}
$('open-glossary').addEventListener('click',()=>{showGlossary();$('glossary-dialog').showModal();});$('glossary-search').addEventListener('input',showGlossary);
$('open-journal').addEventListener('click',()=>{$('journal-summary').innerHTML=`<ul>${cards.map(c=>`<li>${mastered(c,state)?'✓':'○'} ${c.title} <span>${state.cards[c.id].evidence.length}/${c.required.length} 份線索</span></li>`).join('')}</ul><p>階段測驗：${Object.entries(stages).map(([id,v])=>v.questions.filter(q=>state.assessments['stage-'+id]?.[q.id]===q.answer).length+'/'+v.questions.length).join(' · ')}</p>`;$('journal-notes').value=state.notes;$('journal-dialog').showModal();});$('journal-notes').addEventListener('input',()=>{state.notes=$('journal-notes').value;save();});document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$('export-journal').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({chapter:'反應速率與平衡',exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='time-alchemy-journal.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
route();updateCertificate();if(/^#card-(?:[1-9]|10)$/.test(location.hash))requestAnimationFrame(()=>document.querySelector(location.hash).scrollIntoView({behavior:'instant'}));
